/**
 * Event Service Client
 * Fetches events from local API server
 */

const API_BASE_URL = 'http://localhost:8080';

/**
 * Generic fetch wrapper
 */
async function fetchFromAPI(endpoint) {
  try {
    const response = await fetch(`${API_BASE_URL}${endpoint}`);
    if (!response.ok) {
      console.error(`[EventService] HTTP error: ${response.status}`);
      return null;
    }
    return await response.json();
  } catch (err) {
    console.error(`[EventService] Fetch error: ${err.message}`);
    return null;
  }
}

/**
 * Fetch Ticketmaster events only
 */
export async function fetchTicketmasterEvents() {
  const data = await fetchFromAPI('/events');

  if (!data) {
    return { events: [], count: 0, error: 'API unavailable' };
  }

  return data.ticketmaster.events || [];
}

/**
 * Fetch all events (Ticketmaster + other sources)
 */
export async function fetchAllEventsViaServer() {
  const data = await fetchFromAPI('/events');

  if (!data) {
    return { events: [], sources: [], error: 'API unavailable' };
  }

  const allEvents = [];

  // Add Ticketmaster events (source is already set by API server)
  if (data.ticketmaster?.events) {
    allEvents.push(...data.ticketmaster.events);
  }

  // Add Kulturhuset events
  if (data.otherSources?.sources?.kulturhuset) {
    allEvents.push(...data.otherSources.sources.kulturhuset);
  }

  // Add Malmö Live events (source is normalized by API server)
  if (data.otherSources?.sources?.malmolive) {
    allEvents.push(...data.otherSources.sources.malmolive);
  }

  // Return available sources from API server for dropdown
  // The API server provides sources based on what's actually available
  const sources = data.sources || [];

  return {
    events: allEvents,
    sources: sources,
    count: allEvents.length,
    ticketmasterCount: data.ticketmaster?.count || 0,
  };
}

/**
 * Fetch events from Supabase (normalized storage)
 * This is the preferred endpoint when Supabase has data
 */
export async function fetchFromSupabase() {
  const data = await fetchFromAPI('/supabase-events');

  if (!data || data.error) {
    console.warn('[EventService] Supabase fetch failed, falling back to direct API');
    return null;
  }

  return {
    events: data.events || [],
    sources: data.sources || [],
    count: data.count || 0,
  };
}

/**
 * Fetch events with automatic fallback
 * Tries Supabase first, then falls back to direct API
 */
export async function fetchEventsSmart() {
  // Try Supabase first (normalized data)
  const supabaseData = await fetchFromSupabase();

  if (supabaseData && supabaseData.events.length > 0) {
    console.log('[EventService] Using Supabase (normalized) events');
    return supabaseData;
  }

  // Fall back to direct API
  console.log('[EventService] Falling back to direct API');
  return fetchAllEventsViaServer();
}

/**
 * Health check for API server
 */
export async function checkHealth() {
  const data = await fetchFromAPI('/health');

  if (!data) {
    return { connected: false, error: 'Cannot reach API server' };
  }

  return {
    connected: true,
    status: data.status,
    ticketmasterKey: data.ticketmasterKey,
  };
}

// Export for use in App.js
export const fetchEvents = fetchAllEventsViaServer;
export const fetchEventsFromSupabase = fetchEventsSmart; // Uses Supabase when available
export { API_BASE_URL };

