/**
 * Event Service Client
 * Fetches events from local API server
 * 
 * PRIMARY: Supabase (normalized, canonicalized events)
 * FALLBACK: Direct API (only if USE_DIRECT_API_FALLBACK=true)
 */

const API_BASE_URL = 'http://localhost:8080';

// Feature flag: Set to true for production (Supabase only)
const USE_DIRECT_API_FALLBACK = false;

/**
 * Generic fetch wrapper
 */
async function fetchFromAPI(endpoint) {
  try {
    const response = await fetch(`${API_BASE_URL}${endpoint}`);
    if (!response.ok) {
      console.error(`[EventService] HTTP error: ${response.status}`);
      return null;
    }
    return await response.json();
  } catch (err) {
    console.error(`[EventService] Fetch error: ${err.message}`);
    return null;
  }
}

/**
 * Fetch events from Supabase (normalized storage)
 * This is the PRIMARY and ONLY source for events in normal operation
 */
export async function fetchFromSupabase() {
  const data = await fetchFromAPI('/supabase-events');

  if (!data || data.error) {
    console.error('[EventService] Supabase fetch failed');
    return { 
      events: [], 
      sources: [], 
      metadata: {
        data_source: 'supabase',
        fallback_used: false,
        error: data?.error || 'Supabase unavailable'
      }
    };
  }

  return {
    events: data.events || [],
    sources: data.sources || [],
    count: data.count || 0,
    metadata: {
      data_source: 'supabase',
      fallback_used: false,
      available_sources: data.sources || [],
      total_count: data.count || 0,
      last_ingested_at: data.last_ingested_at || null,
      query_params: data.query_params || {}
    }
  };
}

/**
 * DEPRECATED: Fetch events directly from provider APIs
 * This endpoint is for debugging only - do not use in production
 */
export async function fetchDirectFromAPIs() {
  const data = await fetchFromAPI('/debug-direct-events');

  if (!data) {
    return { events: [], sources: [], error: 'Direct API unavailable' };
  }

  const allEvents = [];

  if (data.ticketmaster?.events) {
    allEvents.push(...data.ticketmaster.events);
  }

  if (data.otherSources?.sources?.kulturhuset) {
    allEvents.push(...data.otherSources.sources.kulturhuset);
  }

  if (data.otherSources?.sources?.malmolive) {
    allEvents.push(...data.otherSources.sources.malmolive);
  }

  return {
    events: allEvents,
    sources: data.sources || [],
    count: allEvents.length,
    metadata: {
      data_source: 'direct_api',
      fallback_used: true,
      warning: 'DEPRECATED: Using direct API, not normalized data'
    }
  };
}

/**
 * Fetch events - Supabase only (production mode)
 * Returns clear metadata about data source
 */
export async function fetchEventsSupabaseOnly() {
  return fetchFromSupabase();
}

/**
 * Fetch events with fallback (development mode only)
 * WARNING: Only use when USE_DIRECT_API_FALLBACK=true
 */
export async function fetchEventsWithFallback() {
  const supabaseData = await fetchFromSupabase();

  if (supabaseData.events.length > 0) {
    console.log('[EventService] Using Supabase events');
    return supabaseData;
  }

  // Only use fallback if explicitly enabled
  if (USE_DIRECT_API_FALLBACK) {
    console.warn('[EventService] WARNING: Falling back to direct API (not normalized!)');
    return fetchDirectFromAPIs();
  }

  // No fallback - return empty with error metadata
  return {
    events: [],
    sources: [],
    metadata: {
      data_source: 'supabase',
      fallback_used: false,
      error: 'No events in Supabase, fallback disabled'
    }
  };
}

/**
 * Health check for API server
 */
export async function checkHealth() {
  const data = await fetchFromAPI('/health');

  if (!data) {
    return { connected: false, error: 'Cannot reach API server' };
  }

  return {
    connected: true,
    status: data.status,
    ticketmasterKey: data.ticketmasterKey,
    supabase: data.supabase,
    ingestion: data.ingestion || null,
  };
}

// Export for use in App.js
export const fetchEvents = fetchEventsSupabaseOnly;
export const fetchEventsFromSupabase = fetchEventsWithFallback;
export { API_BASE_URL, USE_DIRECT_API_FALLBACK };

